// Service worker: offline app shell. The precache list and VERSION are generated by
// tools/stamp-sw.mjs — run it after changing any app file.
const VERSION = 'c4993b8da4c6';
const CACHE = `todaytime-pro-${VERSION}`;
const PRECACHE = [
  './',
  'apple-touch-icon.png',
  'icon-192.png',
  'icon-512.png',
  'index.html',
  'manifest.json',
  'src/core/ics.js',
  'src/core/migrate.js',
  'src/core/model.js',
  'src/core/parse.js',
  'src/core/predict.js',
  'src/core/recurrence.js',
  'src/core/reflow.js',
  'src/core/schedule.js',
  'src/core/time.js',
  'src/core/tracker.js',
  'src/data/actions.js',
  'src/data/storage.js',
  'src/data/store.js',
  'src/main.js',
  'src/services/exporter.js',
  'src/services/moodle.js',
  'src/services/notify.js',
  'src/styles/app.css',
  'src/ui/app.js',
  'src/ui/components.js',
  'src/ui/forms.js',
  'src/ui/h.js',
  'src/ui/icons.js',
  'src/ui/ops.js',
  'src/ui/overlays.js',
  'src/ui/runtime.js',
  'src/ui/screens/calendar.js',
  'src/ui/screens/school.js',
  'src/ui/screens/settings.js',
  'src/ui/screens/tasks.js',
  'src/ui/screens/today.js',
  'src/vendor/hooks.mjs',
  'src/vendor/htm.mjs',
  'src/vendor/preact.mjs',
];

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE).then((c) => c.addAll(PRECACHE.map((p) => new Request(p, { cache: 'reload' })))));
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) if (key.startsWith('todaytime-pro-') && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const scope = new URL(self.registration.scope);
  const rel = url.pathname.slice(scope.pathname.length);
  if (rel.startsWith('legacy/')) return; // the old app is served straight from the network

  if (req.mode === 'navigate') {
    // App shell: cached copy first (instant, offline), refreshed by SW updates.
    event.respondWith(caches.match('./', { ignoreSearch: true }).then((hit) => hit || fetch(req)));
    return;
  }
  event.respondWith(caches.match(req, { ignoreSearch: true }).then((hit) => hit || fetch(req).then((res) => {
    if (res.ok && res.type === 'basic') { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(req, copy)); }
    return res;
  })));
});

self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  event.waitUntil((async () => {
    const all = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    if (all[0]) return all[0].focus();
    return self.clients.openWindow('./');
  })());
});
